package ru.neverland.mintcontracts.procurement;

import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;

public final class ProcurementSmoke {
    static int checks;
    static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
    @FunctionalInterface interface Work{void run()throws Exception;}
    static void denied(Work work,String why)throws Exception{try{work.run();throw new AssertionError("accepted: "+why);}catch(IllegalArgumentException|ExecutionException expected){checks++;}}
    static <T>T done(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(10,TimeUnit.SECONDS);}
    static final UUID T=UUID.randomUUID(),ACTOR=UUID.randomUUID();
    static ProcurementOrder quote(String project){long now=System.currentTimeMillis();return new ProcurementOrder(UUID.randomUUID(),T,"Город",ACTOR,"Mayor",project,1,"Ратуша","frozen-needs","a".repeat(64),"opaque-normalized-item","Дубовые брёвна",64,640,86400,now,now+30000,"QUOTE",0,"Подтвердите точную поставку",null,"","");}
    static Map<String,Object> proof(ProcurementOrder r,String status,boolean refund){var row=new HashMap<String,Object>();row.put("operation",(refund?r.refundId():r.id()).toString());row.put("town",r.town().toString());row.put("actor",(refund?r.refundActor():r.actor()).toString());row.put("reason",refund?r.refundReason():r.bankReason());row.put("source","contracts");row.put("category","infrastructure");row.put("cents",r.cents());row.put("owner","NeverLandTownyContracts");row.put("status",status);row.put("kind",refund?"REFUND":"DEBIT");row.put("backingDebit",refund?r.id().toString():"");row.put("backingAvailable",!refund&&status.equals("PAID"));return row;}
    public static void main(String[] args)throws Exception{
        Path file=Files.createTempDirectory("procurement-native-ledger-").resolve("procurement.sqlite");var repo=new ProcurementRepository(file);done(repo.ready());final var first=repo;var q=quote("town_hall");done(repo.quote(q));check(done(repo.get(q.id())).equals(q),"exact quote terms persist independently of municipal contracts");done(repo.quote(q));check(done(repo.requests(T,1)).size()==1,"same immutable quote ID does not create duplicate entries");denied(()->done(first.quote(q.state("FUNDING",0,"changed"))),"same request with changed terms is refused");
        var funding=done(repo.funding(q.id()));check(funding.state().equals("FUNDING")&&funding.amount()==64&&funding.cents()==640,"intent ACK freezes exact quantity and city-funded reward before bank call");
        check(done(repo.bank(q.id(),proof(funding,"PREPARED",false),false)).state().equals("FUNDING"),"budget reservation is not confirmed bank funding");denied(()->done(first.publishing(q.id())),"no municipal contract publication before stable PAID receipt");
        var foreign=proof(funding,"PAID",false);foreign.put("town",UUID.randomUUID().toString());denied(()->done(first.bank(q.id(),foreign,false)),"other city's payment cannot finance this quote");var wrongAmount=proof(funding,"PAID",false);wrongAmount.put("cents",641);denied(()->done(first.bank(q.id(),wrongAmount,false)),"different amount cannot finance quote");var refunded=proof(funding,"PAID",false);refunded.put("backingAvailable",false);denied(()->done(first.bank(q.id(),refunded,false)),"already returned or reserved-for-return backing cannot be published");
        var review=done(repo.bank(q.id(),proof(funding,"REVIEW",false),false));check(review.state().equals("REVIEW"),"ambiguous bank result remains review, not another automatic debit");var paid=done(repo.bank(q.id(),proof(funding,"PAID",false),false));check(paid.state().equals("FUNDED"),"only exact authoritative PAID enables publication intent");var publishing=done(repo.publishing(q.id()));long started=publishing.started();check(publishing.state().equals("PUBLISHING")&&started>0,"fixed publication timestamp is durable before legacy contract save");check(done(repo.publishing(q.id())).started()==started,"publication retry cannot extend the promised contract deadline");denied(()->done(first.cancel(q.id(),ACTOR,"Mayor",false)),"uncertain publication cannot request a full refund");var published=done(repo.published(q.id(),ACTOR,"Mayor",false));check(published.state().equals("PUBLISHED"),"municipal receipt closes the local publication intent");denied(()->done(first.cancel(q.id(),ACTOR,"Mayor",true)),"published escrow can never use full procurement refund");done(repo.published(q.id(),ACTOR,"Mayor",true));check(done(repo.get(q.id())).state().equals("SETTLED"),"closed legacy contract remains an idempotent receipt");
        var r=quote("seed_vault");done(repo.quote(r));done(repo.funding(r.id()));done(repo.bank(r.id(),proof(r,"PAID",false),false));var cancel=done(repo.cancel(r.id(),ACTOR,"Mayor",true));check(cancel.state().equals("REFUNDING")&&cancel.refundActor().equals(ACTOR),"full refund has its own durable immutable actor and operation");check(done(repo.cancel(r.id(),UUID.randomUUID(),"NewMayor",true)).refundActor().equals(ACTOR),"new mayor resumes the same refund rather than changing its bank payload");var otherDebit=proof(cancel,"PAID",true);otherDebit.put("backingDebit",q.id().toString());denied(()->done(first.bank(r.id(),otherDebit,true)),"refund proof must identify exact original paid debit");check(done(repo.bank(r.id(),proof(cancel,"REVIEW",true),true)).state().equals("REFUNDING"),"ambiguous refund stays pending without a second automatic deposit");done(repo.bank(r.id(),proof(cancel,"PAID",true),true));done(repo.bank(r.id(),proof(cancel,"PAID",true),true));check(done(repo.get(r.id())).state().equals("REFUNDED"),"exact refund receipt applied once");denied(()->done(first.publishing(r.id())),"returned escrow cannot become municipal contract");
        var free=quote("citadel");done(repo.quote(free));check(done(repo.cancel(free.id(),ACTOR,"Mayor",false)).state().equals("CANCELLED"),"unpaid quote cancellation has no bank operation");
        var one=quote("admiralty");var two=quote("admiralty");done(repo.quote(one));done(repo.quote(two));done(repo.funding(one.id()));denied(()->done(first.funding(two.id())),"parallel identical material funding intents cannot overbook the city demand");
        var fault=quote("trade_exchange");done(repo.quote(fault));try(var db=DriverManager.getConnection("jdbc:sqlite:"+file);var statement=db.createStatement()){statement.execute("CREATE TRIGGER fail_quote_audit BEFORE INSERT ON history WHEN NEW.kind='FUNDING' AND NEW.request='"+fault.id()+"' BEGIN SELECT RAISE(ABORT,'fixture audit intent failure'); END");}denied(()->done(first.funding(fault.id())),"SQL failure between funding state and history rolls back both");done(repo.closeAsync());try(var db=DriverManager.getConnection("jdbc:sqlite:"+file);var statement=db.createStatement()){statement.execute("DROP TRIGGER fail_quote_audit");}repo=new ProcurementRepository(file);done(repo.ready());check(done(repo.get(fault.id())).state().equals("QUOTE"),"failed intent was never made bank-ready across restart");check(done(repo.get(q.id())).state().equals("SETTLED")&&done(repo.get(r.id())).state().equals("REFUNDED"),"final accounting and refunds survive full repository restart");check(!done(repo.auditPending()).isEmpty(),"all canonical changes carry durable administrative outbox entries");done(repo.closeAsync());System.out.println("ProcurementSmoke PASS "+checks+" checks; exact financing/refund proofs, no unpaid publication, duplicate limits, rollback and restart");
    }
}
